(window.__AC=window.__AC||{});__AC["assets2"]=(__AC["assets2"]||'')+"Object.assign(window.ASSETS_LINES,{\"l2_a\":{\"s\":\"avram\",\"t\":\"Ирма, город встал перед Старым мостом. Пролёты обрушены. Пройди по фермам и открой путевой затвор на той стороне.\"},\"l2_b\":{\"s\":\"irma\",\"t\":\"Ветер с ночной стороны. Держусь крепче.\"},\"l2_wind\":{\"s\":\"avram\",\"t\":\"Порывы идут волнами. Когда загудят тросы — прячься за опору и пережди.\"},\"l2_zip\":{\"s\":\"irma\",\"t\":\"Старые тросы канатки. Зацеплюсь Клювом — и с ветерком.\"},\"l2_drone\":{\"s\":\"avram\",\"t\":\"Над мостом кружит фонарщик Гильдии. Что они здесь ищут? Не попадайся в луч.\"},\"l2_end\":{\"s\":\"irma\",\"t\":\"Затвор открыт! Дед, веди Орсо на мост. А я — дальше, в тень.\"},\"l3_a\":{\"s\":\"avram\",\"t\":\"Дальше только ночь. Стрелка обходного пути вмёрзла в лёд. Без неё нам не пройти.\"},\"l3_ice\":{\"s\":\"irma\",\"t\":\"Лёд как стекло. Тормозить заранее.\"},\"l3_icicle\":{\"s\":\"avram\",\"t\":\"Сосульки над путями тяжёлые, как рельсы. Услышишь треск — уходи.\"},\"s1\":{\"s\":\"narr\",\"t\":\"Бортовой журнал «Зари», первый день после посадки. Корабль больше не взлетит. Мы остаёмся. Пусть дети запомнят: мы пришли со звёзд.\"},\"s2\":{\"s\":\"narr\",\"t\":\"Записка путейца: рельсы кладут на ходу. Отстанешь от укладчиков на час — и твоя смена станет последней.\"},\"s3\":{\"s\":\"narr\",\"t\":\"Устав Гильдии Фонарщиков, статья первая: свет принадлежит тем, кто его хранит.\"},\"s4\":{\"s\":\"narr\",\"t\":\"Детская считалка Орсо: солнце жжёт, а ночь не ждёт. Кто устал — тот не дойдёт.\"},\"s5\":{\"s\":\"narr\",\"t\":\"Журнал «Зари», последняя запись. Мы замкнули путь в кольцо. Кто держит кольцо — держит всех. Не отдавайте его одному.\"},\"s6\":{\"s\":\"narr\",\"t\":\"Пометка на полях, свежими чернилами: «Орсо — лишний. Снять с кольца». Подпись: Гильдия.\"},\"c1\":{\"s\":\"irma\",\"t\":\"Хвост горит. Значит, вперёд.\"}});\nObject.assign(window.ASSETS_AUDIO,{\"m_bridge\":\"";